package com.capstone.fraudcase.api.dto;

import com.capstone.fraudcase.api.validation.MaskedReference;
import com.capstone.fraudcase.api.validation.SafeText;
import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Case intake. The case ID is generated by the server and the analyst ID comes from the authenticated
 * principal, so neither is accepted from the client.
 */
public record CreateCaseRequest(
        @NotBlank @MaskedReference
        String customerReference,

        @MaskedReference
        String cardReference,

        @NotNull @Valid
        TransactionClaimRequest transaction,

        @NotBlank @Size(max = 2000) @SafeText
        String customerStatement,

        @NotNull @AssertTrue(message = "must be true: only synthetic data may be submitted")
        Boolean syntheticDataConfirmed,

        @NotNull @AssertTrue(message = "must be true: every case requires human review")
        Boolean reviewRequired) {
}
